import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import DonationForm from './components/DonationForm';
import ProgressBar from './components/ProgressBar';
import DonationHistory from './components/DonationHistory';
import TopDonors from './components/TopDonors';
import './App.css';

function App() {
  const [fundData, setFundData] = useState({
    total_raised: 0,
    goal: 50000,
    top_donors: [],
    recent_donations: []
  });

  const fetchDonations = async () => {
    try {
      const response = await axios.get('http://localhost:5000/get-donations');
      setFundData(response.data);
    } catch (error) {
      console.error('Error fetching donations:', error);
    }
  };

  useEffect(() => {
    fetchDonations();
  }, []);

  const handleDonationSuccess = () => {
    fetchDonations();
  };

  return (
    <div className="app">
      <ToastContainer />
      <header>
        <h1>Help Me Get My Dream GT Bike</h1>
      </header>

      <main>
        <div className="left-column">
          <ProgressBar raised={fundData.total_raised} goal={fundData.goal} />
          <DonationForm onDonationSuccess={handleDonationSuccess} />
        </div>

        <div className="right-column">
          <TopDonors donors={fundData.top_donors} />
          <DonationHistory donations={fundData.recent_donations} />
        </div>
      </main>

      <footer>
        <p>Thank you for your support! Every contribution helps me get closer to my dream bike.</p>
      </footer>
    </div>
  );
}

export default App;
